import{_ as e,o as a,a as l,b as o}from"./app.DKoEZOcr.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"Tensor API","link":"/api/SIMD-API/tensor_api/tensor_api"}]},"headers":[],"relativePath":"api/SIMD-API/tensor_api/tensor_api.md","filePath":"api/SIMD-API/tensor_api/tensor_api.md","outlineHeaders":[{"level":2,"title":"接口分层","slug":"接口分层","link":"#接口分层"},{"level":2,"title":"能力范围","slug":"能力范围","link":"#能力范围"},{"level":2,"title":"与C API配合使用","slug":"与C-API配合使用","link":"#与C-API配合使用"}],"lastUpdated":1788319986000}'),d={name:"api/SIMD-API/tensor_api/tensor_api.md"};function c(r,t,i,n,s,_){return a(),l("div",null,[...t[0]||(t[0]=[o(`<div><article class="markdown-body"><h1>Tensor API</h1><p>Tensor API是一套面向Ascend C算子开发的基础编程接口，使用Tensor和Layout统一描述数据的存储位置、数据类型、尺寸大小和排列规则，并基于这些信息完成数据搬运、矩阵计算和矢量计算，减少开发者手工组织硬件指令参数和数据排布的工作量。</p><p>Tensor API提供基于Tensor的数据搬运、矩阵计算和矢量计算能力。开发者可以在同一个核函数中组合使用Tensor API和C API，以实现完整的算子功能。</p><h2 id="接口分层">接口分层<a class="header-anchor" href="#接口分层">​</a></h2><p><strong>表1</strong> 接口分层说明</p><table><thead><tr><th align="left">层级</th><th align="left">作用</th><th align="left">主要内容</th></tr></thead><tbody><tr><td align="left">Tensor+Layout</td><td align="left">描述数据的存储位置、数据类型、尺寸大小和排列规则。</td><td align="left">Tensor、Pointer、Layout、Shape、Stride和Coord。</td></tr><tr><td align="left">Arch</td><td align="left">提供数据搬运和矩阵计算相关的Operation、用于描述编译期特性的Trait、用于描述运行时参数的Params，以及矢量计算接口。</td><td align="left">Operation：<code>copy_gm_to_l1</code>、<code>mmad_operation</code><br>Trait：<code>gm_to_l1_trait</code><br>Params：<code>l0c_to_gm_params</code><br>矢量计算：<code>select</code>、<code>fill</code>。</td></tr><tr><td align="left">Atom</td><td align="left">将Operation、Trait和可选Params组合为数据搬运或矩阵计算的原子对象。</td><td align="left"><code>copy_atom</code>、<code>mmad_atom</code>。</td></tr><tr><td align="left">Algorithm</td><td align="left">提供面向Tensor的数据搬运和矩阵计算的统一调用入口。</td><td align="left"><code>copy</code>、<code>make_copy</code>、<code>mmad</code>和<code>make_mmad</code>。</td></tr></tbody></table><p>使用Tensor API时，需要包含统一入口头文件：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;tensor_api/tensor.h&quot;</span>
</code></pre></div><h2 id="能力范围">能力范围<a class="header-anchor" href="#能力范围">​</a></h2><ul><li><a href="layout/layout_structure.html">Layout</a>：介绍Layout、Shape、Stride和Coord的构造、数据排布描述及相关属性查询能力。</li><li><a href="tensor/tensor_structure.html">Tensor</a>：介绍Tensor和Pointer的创建、访问与切片能力。</li><li><a href="algorithm.html">Algorithm</a>：介绍数据搬运和矩阵计算中Operation、Trait与Atom的作用、组合关系及使用方式。</li><li><a href="data_move/data_move.html">数据搬运</a>：介绍多种数据搬运通路，包括Global Memory与Unified Buffer之间的双向搬运，Global Memory到L1 Buffer的搬运等。</li><li><a href="matrix_compute/matrix_compute.html">矩阵计算</a>：介绍矩阵数据搬入、矩阵乘加、矩阵结果搬出和相关关键特性。</li><li><a href="reg_vector_compute/reg_vector_compute.html">reg矢量计算</a>：介绍矢量计算的搬入、矢量计算的搬出、寄存器数据搬入搬出、Mask寄存器计算和类型转换。</li><li><a href="utils/tool_functions.html">工具接口</a>：介绍编译期整数、维度保留标记和Layout Pattern查询接口，以及Layout、Tensor、Coord、Shape和量化参数的类型判断等工具接口的使用方式。</li><li><a href="deprecated_interface/deprecated_interface.html">废弃接口</a>：介绍用于兼容的大驼峰风格接口。</li></ul><h2 id="与C-API配合使用">与C API配合使用<a class="header-anchor" href="#与C-API配合使用">​</a></h2><p>Tensor API提供基于Tensor和Layout的数据组织、数据搬运、矩阵计算和矢量计算能力，适合构建算子的主要数据处理流程。缓存控制、同步控制、系统变量、原子操作和初始化等底层控制能力由C API提供。开发者可以在同一个核函数中组合使用Tensor API和C API，以实现完整的算子功能。</p><p>Tensor API和C API的接口支持范围及参数约束相互独立，混合使用时需要同时满足两类接口的要求。</p><p>Tensor API未完整覆盖的能力及对应C API资料如下。</p><p><strong>表2</strong> C API能力说明</p><table><thead><tr><th align="left">能力</th><th align="left">C API用途</th><th align="left">接口示例</th><th align="left">相关资料</th></tr></thead><tbody><tr><td align="left">初始化</td><td align="left">将全局控制状态恢复为初始值。</td><td align="left"><code>asc_init</code></td><td align="left"><a href="../c_api/utils/sys_init/asc_init.html">asc_init</a></td></tr><tr><td align="left">缓存控制</td><td align="left">Data Cache或Instruction Cache预加载、刷新和失效。</td><td align="left"><code>asc_datacache_preload</code>、<code>asc_dcci</code>、<code>asc_dci</code></td><td align="left"><a href="../c_api/cache_ctrl/cache_ctrl.html">缓存控制</a></td></tr><tr><td align="left">同步控制</td><td align="left">流水线同步和核间同步。</td><td align="left"><code>asc_lock</code>、<code>asc_unlock</code>、<code>asc_sync_notify</code>、<code>asc_sync_wait</code></td><td align="left"><a href="../c_api/sync/sync.html">同步控制</a></td></tr><tr><td align="left">系统变量</td><td align="left">查询核索引、核数量、系统Cycle等运行信息。</td><td align="left"><code>asc_get_arch_ver</code>、<code>asc_get_core_id</code>、<code>asc_get_system_cycle</code></td><td align="left"><a href="../c_api/utils/sys_var/sys_var.html">系统变量</a></td></tr><tr><td align="left">原子操作</td><td align="left">随路原子操作和指定Global Memory地址的Scalar原子更新。</td><td align="left"><code>asc_set_atomic_add</code>、<code>asc_set_atomic_none</code>、<code>asc_atomic_add</code></td><td align="left"><a href="../c_api/atomic/atomic.html">随路原子操作</a>、<a href="../c_api/scalar_compute/scalar_compute.html">Scalar计算</a></td></tr></tbody></table></article></div>`,1)])])}const f=e(d,[["render",c]]);export{p as __pageData,f as default};
